def clean_question(value):
    if not isinstance(value, dict) or not isinstance(value.get('text'), str):
        return None
    text = value['text'].strip()[:240]
    if not text:
        return None
    choices = value.get('options', [])
    if not isinstance(choices, list):
        choices = []
    choices = list(dict.fromkeys(x.strip()[:90] for x in choices if isinstance(x, str) and x.strip()))[:3]
    return {'text': text, 'options': choices}
